{
    "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
    "contentVersion": "1.0.0.0",
    "metadata": {
        "title": "Forcepoint NGFW - Block URL",
        "description": "Once a new Microsoft Sentinel incident is created, this playbook gets triggered and performs the following actions:\n 1. Fetches a list of potentially malicious URLs.\n 2. For each URL in the list, checks if the URL is already present in URL List Name or not.\n 3. List of all URLs not present in URL List Name is blocked in the firewall by the playbook.",
        "prerequisites": [
            "1. Deploy the Forcepoint SMC Custom Connector before the deployment of this playbook under the same subscription and same resource group as will be used for this playbook. Capture the name of the connector during deployment.",
            "2. Forcepoint SMC API Key should be known to establish a connection with Forcepoint SMC. For API Key [Refer here](http://www.websense.com/content/support/library/ngfw/v610/rfrnce/ngfw_6100_ug_smc-api_a_en-us.pdf )",
            "3. Forcepoint SMC Version number should be known. [Refer here](https://help.stonesoft.com/onlinehelp/StoneGate/SMC/) to download and install Forcepoint SMC and capture the version number for the same.",
            "4. URL list name for blocking IP address present in SMC should be known."
        ],
        "lastUpdateTime": "2022-08-26T07:00:00.000Z",
        "entities": [
            "url"
        ],
        "tags": [
            "Remediation"
        ],
        "support": {
            "tier": "microsoft"
        },
        "author": {
            "name": "Microsoft"
        }
    },
    "parameters": {
        "PlaybookName": {
            "type": "String",
            "defaultValue": "ForcepointNGFW-BlockURL",
            "metadata": {
                "description": "Enter name for playbook without spaces. This playbook blocks malicious URLs in Forcepoint SMC."
            }
        },
        "ForcepointSMCConnectorName": {
            "type": "string",
            "defaultValue": "ForcepointSMC-Connector",
            "metadata": {
                "description": "Enter the name for your Forcepoint SMC Connector without spaces"
            }
        },
        "ForcepointSMCApiKey": {
            "type": "securestring",
            "metadata": {
                "description": "Enter the api key for smc login"
            }
        },
        "VersionNumber": {
            "type": "string",
            "defaultValue": "6.8",
            "metadata": {
                "description": "Enter SMC Version Number"
            }
        },
        "URLListName": {
            "type": "string",
            "metadata": {
                "description": "Enter URL List Name present in SMC"
            }
        }
    },
    "variables": {
        "Forcepoint_Connector": "[concat('ForcepointSMCApiConnector-',parameters('PlaybookName'))]"
    },
    "resources": [
        {
            "type": "Microsoft.Logic/workflows",
            "apiVersion": "2017-07-01",
            "name": "[parameters('PlaybookName')]",
            "location": "[resourceGroup().location]",
            "dependsOn": [
                "[resourceId('Microsoft.Web/connections', variables('Forcepoint_Connector'))]"
            ],
            "properties": {
                "state": "Enabled",
                "definition": {
                    "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                        "$connections": {
                            "defaultValue": {},
                            "type": "Object"
                        }
                    },
                    "triggers": {
                        "manual": {
                            "type": "Request",
                            "kind": "Http",
                            "inputs": {
                                "schema": {
                                    "properties": {
                                        "URLs": {
                                            "items": {
                                                "properties": {
                                                    "url": {
                                                        "type": "string"
                                                    }
                                                },
                                                "required": [
                                                    "url"
                                                ],
                                                "type": "object"
                                            },
                                            "type": "array"
                                        }
                                    },
                                    "type": "object"
                                }
                            }
                        }
                    },
                    "actions": {
                        "Check_if_body_present_from_output": {
                            "actions": {
                                "Check_Login_Status": {
                                    "runAfter": {
                                        "Login": [
                                            "Succeeded",
                                            "Failed",
                                            "Skipped",
                                            "TimedOut"
                                        ]
                                    },
                                    "cases": {
                                        "200_Success_OK": {
                                            "case": 200,
                                            "actions": {
                                                "Condition_to_if_URL_list_is_present_in_SMC_or_not": {
                                                    "actions": {
                                                        "Condition_to_check_if_needs_to_be_terminated": {
                                                            "actions": {
                                                                "Terminate_the_playbook_if_API_issue_occurred": {
                                                                    "runAfter": {},
                                                                    "type": "Terminate",
                                                                    "inputs": {
                                                                        "runError": {
                                                                            "message": "Having API issue in playbook"
                                                                        },
                                                                        "runStatus": "Failed"
                                                                    },
                                                                    "description": "Terminate the playbook if API issue occurred"
                                                                }
                                                            },
                                                            "runAfter": {
                                                                "Create_HTML_table_for_Add_comment_to_incident": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "else": {
                                                                "actions": {
                                                                    "Response": {
                                                                        "runAfter": {},
                                                                        "type": "Response",
                                                                        "kind": "Http",
                                                                        "inputs": {
                                                                            "body": "@{outputs('Forcepoint_Logo')}Forcepoint NGFW-Block URL\nThe below URL are found to be malicious and playbook taken action against to that URLs.\n\n@{body('Create_HTML_table_for_Add_comment_to_incident')}",
                                                                            "statusCode": 200
                                                                        }
                                                                    }
                                                                }
                                                            },
                                                            "expression": {
                                                                "and": [
                                                                    {
                                                                        "equals": [
                                                                            "@variables('Terminate')",
                                                                            "APIError"
                                                                        ]
                                                                    }
                                                                ]
                                                            },
                                                            "type": "If",
                                                            "description": "Condition to check if needs to be terminated"
                                                        },
                                                        "Create_HTML_table_for_Add_comment_to_incident": {
                                                            "runAfter": {
                                                                "Upload_URL_to_URL_list": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "type": "Table",
                                                            "inputs": {
                                                                "columns": [
                                                                    {
                                                                        "header": "URL",
                                                                        "value": "@item()?['URLAddres']"
                                                                    },
                                                                    {
                                                                        "header": "URL-List-Name",
                                                                        "value": "@variables('URL list name')"
                                                                    },
                                                                    {
                                                                        "header": "URL-Status",
                                                                        "value": "@item()?['URLStatus']"
                                                                    },
                                                                    {
                                                                        "header": "Action-Taken",
                                                                        "value": "@item()?['Action']"
                                                                    }
                                                                ],
                                                                "format": "HTML",
                                                                "from": "@variables('Arrayforallactions')"
                                                            },
                                                            "description": "Creating a HTML table from all actions taken by URLs"
                                                        },
                                                        "Get_URL_address": {
                                                            "runAfter": {},
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "headers": {
                                                                    "Accept": "application/json",
                                                                    "Content-Type": "application/json"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "get",
                                                                "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements/url_list_application/@{encodeURIComponent(last(split(body('Get_URL_List')?['result']?[0]?['href'],'/')))}"
                                                            }
                                                        },
                                                        "Looping_URLs": {
                                                            "foreach": "@triggerBody()?['URLs']",
                                                            "actions": {
                                                                "Check_the_result_length_from_filter_output": {
                                                                    "actions": {
                                                                        "Append_to_array_of_all_actions": {
                                                                            "runAfter": {
                                                                                "Set_variable_to_consolidate_variable_set": [
                                                                                    "Succeeded"
                                                                                ]
                                                                            },
                                                                            "type": "AppendToArrayVariable",
                                                                            "inputs": {
                                                                                "name": "Arrayforallactions",
                                                                                "value": "@variables('Consolidatevrbl')"
                                                                            }
                                                                        },
                                                                        "Set_variable_to_consolidate_variable_set": {
                                                                            "runAfter": {},
                                                                            "type": "SetVariable",
                                                                            "inputs": {
                                                                                "name": "Consolidatevrbl",
                                                                                "value": {
                                                                                    "Action": "Already blocked",
                                                                                    "IncidentSeverity": "",
                                                                                    "URLAddres": "@{items('Looping_URLs')?['url']}",
                                                                                    "URLStatus": "Blocked"
                                                                                }
                                                                            }
                                                                        }
                                                                    },
                                                                    "runAfter": {},
                                                                    "else": {
                                                                        "actions": {
                                                                            "Append_to_array_variable_to_Not_exit_URL_address": {
                                                                                "runAfter": {},
                                                                                "type": "AppendToArrayVariable",
                                                                                "inputs": {
                                                                                    "name": "URL Address",
                                                                                    "value": "@items('Looping_URLs')?['Url']"
                                                                                },
                                                                                "description": "Append to array variable to Not exit URL address"
                                                                            },
                                                                            "Append_to_array_variable_to_array_for_actions": {
                                                                                "runAfter": {
                                                                                    "Set_variable_for_consolidate_variable": [
                                                                                        "Succeeded"
                                                                                    ]
                                                                                },
                                                                                "type": "AppendToArrayVariable",
                                                                                "inputs": {
                                                                                    "name": "Arrayforallactions",
                                                                                    "value": "@variables('Consolidatevrbl')"
                                                                                },
                                                                                "description": "Append to array variable to array for actions"
                                                                            },
                                                                            "Set_variable_for_consolidate_variable": {
                                                                                "runAfter": {
                                                                                    "Append_to_array_variable_to_Not_exit_URL_address": [
                                                                                        "Succeeded"
                                                                                    ]
                                                                                },
                                                                                "type": "SetVariable",
                                                                                "inputs": {
                                                                                    "name": "Consolidatevrbl",
                                                                                    "value": {
                                                                                        "Action": "Blocked by playbook",
                                                                                        "IncidentSeverity": "",
                                                                                        "URLAddres": "@{items('Looping_URLs')?['Url']}",
                                                                                        "URLStatus": "Blocked"
                                                                                    }
                                                                                },
                                                                                "description": "Set variable for consolidate variable"
                                                                            }
                                                                        }
                                                                    },
                                                                    "expression": {
                                                                        "and": [
                                                                            {
                                                                                "contains": [
                                                                                    "@body('Get_URL_address')?['url_entry']",
                                                                                    "@items('Looping_URLs')?['url']"
                                                                                ]
                                                                            }
                                                                        ]
                                                                    },
                                                                    "type": "If",
                                                                    "description": "We will check for the result output is empty or exist in the policy rule. If result output is empty ,then there is no policy based on URL. And If result ouput is having some information related to URL then there is a policy with respect to URL"
                                                                }
                                                            },
                                                            "runAfter": {
                                                                "Set_URL_address_array_from_SMC_URL_address_list": [
                                                                    "Succeeded"
                                                                ]
                                                            },
                                                            "type": "Foreach",
                                                            "description": "Here we are looping each URL and check whether it is blocked or not "
                                                        },
                                                        "Set_URL_address_array_from_SMC_URL_address_list": {
                                                            "runAfter": {
                                                                "Get_URL_address": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "type": "SetVariable",
                                                            "inputs": {
                                                                "name": "URL Address",
                                                                "value": "@body('Get_URL_address')?['url_entry']"
                                                            },
                                                            "description": "Set URL address array from SMC URL address list"
                                                        },
                                                        "Upload_URL_to_URL_list": {
                                                            "runAfter": {
                                                                "Looping_URLs": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "body": {
                                                                    "key": "@last(split(body('Get_URL_List')?['result']?[0]?['href'],'/'))",
                                                                    "name": "@variables('URL list name')",
                                                                    "url_entry": "@variables('URL Address')"
                                                                },
                                                                "headers": {
                                                                    "Accept": "application/json",
                                                                    "Content-Type": "application/json",
                                                                    "If-Match": "@outputs('Get_URL_address')['headers']['ETag']"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "put",
                                                                "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements/url_list_application/@{encodeURIComponent(last(split(body('Get_URL_List')?['result']?[0]?['href'],'/')))}"
                                                            }
                                                        }
                                                    },
                                                    "runAfter": {
                                                        "Get_URL_List": [
                                                            "Succeeded",
                                                            "TimedOut",
                                                            "Skipped",
                                                            "Failed"
                                                        ]
                                                    },
                                                    "else": {
                                                        "actions": {
                                                            "Terminate": {
                                                                "runAfter": {},
                                                                "type": "Terminate",
                                                                "inputs": {
                                                                    "runError": {
                                                                        "message": "@{variables('URL list name')} does not exist in SMC. Please create URL list in SMC before deploy the playbook."
                                                                    },
                                                                    "runStatus": "Failed"
                                                                }
                                                            }
                                                        }
                                                    },
                                                    "expression": {
                                                        "and": [
                                                            {
                                                                "equals": [
                                                                    "@outputs('Get_URL_List')?['statusCode']",
                                                                    200
                                                                ]
                                                            }
                                                        ]
                                                    },
                                                    "type": "If"
                                                },
                                                "Get_URL_List": {
                                                    "runAfter": {},
                                                    "type": "ApiConnection",
                                                    "inputs": {
                                                        "headers": {
                                                            "Accept": "application/json",
                                                            "Content-Type": "application/json"
                                                        },
                                                        "host": {
                                                            "connection": {
                                                                "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                            }
                                                        },
                                                        "method": "get",
                                                        "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements/url_list_application",
                                                        "queries": {
                                                            "Expand": true,
                                                            "Expose Etag": true,
                                                            "URL list": "@variables('URL list name')"
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    },
                                    "default": {
                                        "actions": {
                                            "Set_variable_to_login_unsuccessful": {
                                                "runAfter": {},
                                                "type": "SetVariable",
                                                "inputs": {
                                                    "name": "Error",
                                                    "value": "Error status code @{outputs('Login')['statusCode']}Unsuccessful login attempt."
                                                },
                                                "description": "When unsuccessful login atempt has done then we can bind the error to \"Error\" variable."
                                            },
                                            "Terminate_if_login_is_unsuccessful": {
                                                "runAfter": {
                                                    "Set_variable_to_login_unsuccessful": [
                                                        "Succeeded"
                                                    ]
                                                },
                                                "type": "Terminate",
                                                "inputs": {
                                                    "runError": {
                                                        "message": "@variables('Error')"
                                                    },
                                                    "runStatus": "Failed"
                                                },
                                                "description": "Terminate if login is unsuccessful login attempt"
                                            }
                                        }
                                    },
                                    "expression": "@outputs('Login')['statusCode']",
                                    "type": "Switch"
                                },
                                "Login": {
                                    "runAfter": {},
                                    "type": "ApiConnection",
                                    "inputs": {
                                        "body": {
                                            "authenticationkey": "@variables('SMC API Key')"
                                        },
                                        "headers": {
                                            "Accept": "application/json",
                                            "Content-Type": "application/json"
                                        },
                                        "host": {
                                            "connection": {
                                                "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                            }
                                        },
                                        "method": "post",
                                        "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/login"
                                    },
                                    "description": "Before take an action against to any other api in Forcepoint SMC we need to do login."
                                }
                            },
                            "runAfter": {
                                "Initialize_variable_for_URL_list_name": [
                                    "Succeeded"
                                ]
                            },
                            "else": {
                                "actions": {
                                    "Set_variable_to_error_variable_if_URL_Address_are_not_available_from_sentinel": {
                                        "runAfter": {},
                                        "type": "SetVariable",
                                        "inputs": {
                                            "name": "Error",
                                            "value": "URL not found from sentinel incident."
                                        },
                                        "description": "Binding the error to \"Error\" variable and pass it to incident comment."
                                    },
                                    "Terminate_if_there_are_no_inputs_from_sentinel": {
                                        "runAfter": {
                                            "Set_variable_to_error_variable_if_URL_Address_are_not_available_from_sentinel": [
                                                "Succeeded"
                                            ]
                                        },
                                        "type": "Terminate",
                                        "inputs": {
                                            "runError": {
                                                "message": "@variables('Error')"
                                            },
                                            "runStatus": "Failed"
                                        },
                                        "description": "Terminate the playbook if there are no inputs from sentinel"
                                    }
                                }
                            },
                            "expression": {
                                "and": [
                                    {
                                        "greater": [
                                            "@length(triggerBody())",
                                            0
                                        ]
                                    }
                                ]
                            },
                            "type": "If",
                            "description": "Form this condition, we will check like if body present in the sentinel incident or not and we will check the URL are available or not."
                        },
                        "Forcepoint_Logo": {
                            "runAfter": {
                                "Initialize_variable_to_Error": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Compose",
                            "inputs": "<img src=\"https://upload.wikimedia.org/wikipedia/en/b/b6/Forcepoint.jpg\" alt=\"ForcepointImage\" width=\"32\" height=\"32\">",
                            "description": "Forcepoint logo for comments "
                        },
                        "Initialize_variable_Terminate": {
                            "runAfter": {
                                "Forcepoint_Logo": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Terminate",
                                        "type": "string"
                                    }
                                ]
                            },
                            "description": " This holds the variable terminate to terminate the logic app "
                        },
                        "Initialize_variable_for_URL_Address": {
                            "runAfter": {
                                "SMC_API_Key": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "URL Address",
                                        "type": "array"
                                    }
                                ]
                            },
                            "description": "Binding URL to this URL address variable"
                        },
                        "Initialize_variable_for_URL_list_name": {
                            "runAfter": {
                                "Initialize_variable_Terminate": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "URL list name",
                                        "type": "string",
                                        "value": "[parameters('URLListName')]"
                                    }
                                ]
                            },
                            "description": "Initialize variable for URL list name"
                        },
                        "Initialize_variable_to_Error": {
                            "runAfter": {
                                "Initialize_variable_to_SMC_Api_Version_Number": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Error",
                                        "type": "string"
                                    }
                                ]
                            },
                            "description": "To keep the error into this variable and pass it to wherever required."
                        },
                        "Initialize_variable_to_SMC_Api_Version_Number": {
                            "runAfter": {
                                "Initialize_variable_to_consolidate_variable": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "SMC Api Version Number",
                                        "type": "string",
                                        "value": "[parameters('VersionNumber')]"
                                    }
                                ]
                            },
                            "description": "To keep SMC Api version number. Forcepoint will update the SMC version every year"
                        },
                        "Initialize_variable_to_consolidate_variable": {
                            "runAfter": {
                                "Initialize_variable_to_keep_all_actions": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Consolidatevrbl",
                                        "type": "object"
                                    }
                                ]
                            },
                            "description": "To form a JSON object to pass it into Allaction variable"
                        },
                        "Initialize_variable_to_keep_all_actions": {
                            "runAfter": {
                                "Initialize_variable_for_URL_Address": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Arrayforallactions",
                                        "type": "array"
                                    }
                                ]
                            },
                            "description": "To store URL , severity , action to be taken into one array varriable and we can create a table."
                        },
                        "SMC_API_Key": {
                            "runAfter": {},
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "SMC API Key",
                                        "type": "string",
                                        "value": "[parameters('ForcepointSMCApiKey')]"
                                    }
                                ]
                            },
                            "description": "SMC API Key is to store Api key for login"
                        }
                    },
                    "outputs": {}
                },
                "parameters": {
                    "$connections": {
                        "value": {
                            "ForcepointSMCApiConnector": {
                                "connectionId": "[resourceId('Microsoft.Web/connections', variables('Forcepoint_Connector'))]",
                                "connectionName": "[variables('Forcepoint_Connector')]",
                                "id": "[concat('/subscriptions/',subscription().subscriptionId,'/resourceGroups/',resourceGroup().name,'/providers/Microsoft.Web/customApis/',parameters('ForcepointSMCConnectorName'))]"
                            }
                        }
                    }
                }
            }
        },
        {
            "type": "Microsoft.Web/connections",
            "apiVersion": "2016-06-01",
            "name": "[variables('Forcepoint_Connector')]",
            "location": "[resourceGroup().location]",
            "properties": {
                "api": {
                    "id": "[concat('/subscriptions/',subscription().subscriptionId,'/resourceGroups/',resourceGroup().name,'/providers/Microsoft.Web/customApis/',parameters('ForcepointSMCConnectorName'))]"
                }
            }
        }
    ],
    "outputs": {}
}

