                          "value": "@body('Parse_JSON_for_address_group_dynamic_content')?[0]?['member']"
                        },
                        "description": "This sets address group members"
                      }
                    }
                  },
                  "expression": {
                    "and": [
                      {
                        "greater": [
                          "@length(body('Parse_JSON_for_address_object_dynamic_content'))",
                          0
                        ]
                      }
                    ]
                  },
