                                        "name": "getpages",
                                        "type": "integer",
                                        "value": "@add(div(body('Parse_JSON')?['count'],1000),1)"
                                    }
                                ]
                            }
                        }
                    },
                    "outputs": {}
                },
                "parameters": {}
            }
        }
    ]
