                            }
                        },
                        "For_each_2": {
                            "foreach": "@body('Entities_-_Get_IPs')?['IPs']",
                            "actions": {
                                "Condition_-_Was_the_alert_sent_from_an_Engineering_Workstation": {
                                    "actions": {
                                        "Close_incident_with_reason_-_Sent_from_Engineering_Station": {
                                            "runAfter": {},
                                            "type": "ApiConnection",
