                                                                    "queries": {
                                                                        "idColumn": "Ip address",
                                                                        "source": "groups/groupid"
                                                                    }
                                                                },
                                                                "description": "Take first row -> SourceIp fields"
                                                            },
                                                            "Was_the_remote_access_done_by_an_Authorized_PC": {
                                                                "actions": {
                                                                    "Resolve_incident_-_Authorized_PC": {
                                                                        "runAfter": {},
                                                                        "type": "ApiConnection",
