{
    "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
    "contentVersion": "1.0.0.0",
    "metadata": {
        "title": "Logic Apps Custom Connectors and Playbook templates - ForcepointNGFW",
        "description": "This is a consolidated json file for deploying ForcepointSMC custom connector + ForcepointFUID custom connector + 6 playbooks.",
        "mainSteps": [
            "Teams: 1. Fetches a list of potentially malicious IP addresses 2. Sends the list of all malicious IP address to SOC via adaptive card 3. Soc can block or ignore unblocked IP address as well as unblock or ignore blocked IP address.",
            "Username: 1. Fetches a list of potentially suspicious User Accounts that are part of Azure Active Directory (AAD) through Azure Sentinel 2. If the IP address is not present in the security policy rule then adds to the security policy and closes the incident.",
            "Block IP: 1. Fetches a list of potentially malicious IP addresses 2. If malicious IP address is not blocked by SMC firewall then blocks it.",
            "Block URL: 1. Fetches a list of potentially malicious URLs 2. If malicious URL is not blocked by SMC firewall then blocks it.",
            "Enrichment IP: 1. Fetches a list of potentially malicious IP addresses 2. Enrich the incident with IP status information.",
            "Enrichment URL: 1. Fetches a list of potentially malicious URLs 2. Enrich the incident with URL status information."
        ],
        "prerequisites": [
            "1. Forcepoint SMC API Key should be known.[Refer here](http://www.websense.com/content/support/library/ngfw/v610/rfrnce/ngfw_6100_ug_smc-api_a_en-us.pdf )",
            "2. Forcepoint SMC Version number should be known. [Refer here](https://help.stonesoft.com/onlinehelp/StoneGate/SMC/)",
            "3. Forcepoint FUID service endpoint should be known. (e.g.  https://forcepointdomain:PortNumber/})",
            "4. Forcepoint SMC service endpoint should be known. (e.g.  https://forcepointdomain:PortNumber/})",
            "5. IP address list name for blocking IP address present in SMC should be known.",
            "6. URL list name for blocking URLs present in SMC should be known.",
            "7. Users must have access to Microsoft Teams and they should be a part of a Teams channel and also Power Automate app should be installed in the Microsoft Teams channel."
        ],
        "lastUpdateTime": "2021-07-26T00:00:00.000Z",
        "entities": [ "Url", "Ip" ],
        "tags": [ "Enrichment", "Teams", "Remediation" ],
        "support": {
            "tier": "community"
        },
        "author": {
            "name": "Accenture"
        }
    },
    "parameters": {
        "BlockIPResponseOnTeamsPlaybookName": {
            "type": "String",
            "defaultValue": "BlockIP-ResponseOnTeams-ForcepointNGFW",
            "metadata": {
                "description": "Enter name for BlockIP Response On Teams playbook without spaces. This playbook sends adaptive card for blocking/unblocking IP address."
            }
        },
        "BlockIPByUsernamePlaybookName": {
            "type": "String",
            "defaultValue": "BlockIPAddressByUsername-ForcepointNGFW",
            "metadata": {
                "description": "Enter name for block IP by username playbook without spaces. This playbook will blocks IP address by username in forcepoint SMC."
            }
        },
        "BlockIPPlaybookName": {
            "type": "String",
            "defaultValue": "BlockIPAddress-ForcepointNGFW",
            "metadata": {
                "description": "Enter name for block playbook without spaces. This playbook will blocks the malicious IP address in Forcepoint SMC."
            }
        },
        "BlockURLPlaybookName": {
            "type": "String",
            "defaultValue": "BlockURLs-ForcepointNGFW",
            "metadata": {
                "description": "Enter name for block URL playbook without spaces. This playbook blocks malicious URLs in Forcepoint SMC."
            }
        },
        "EnrichmentIPPlaybookName": {
            "type": "String",
            "defaultValue": "EnrichmentIP-ForcepointNGFW",
            "metadata": {
                "description": "Enter name for enrichment IP playbook without spaces. This playbook will enrich IP status information."
            }
        },
        "EnrichmentURLPlaybookName": {
            "type": "String",
            "defaultValue": "EnrichmentURL-ForcepointNGFW",
            "metadata": {
                "description": "Enter name for enrichment URL playbook without spaces. This playbook will enrich URL status information."
            }
        },
        "ForcepointSMCApiKey": {
            "type": "securestring",
            "metadata": {
                "description": "Enter the api key for smc login"
            }
        },
        "IPListName": {
