                            },
                            "DestinationDevice": {
                                "type": "string"
                            },
                            "DestinationDeviceAddress": {
                                "type": "string"
                            },
                            "DeviceId": {
                                "type": "string"
                            },
                            "ProcessedBySentinel": {
                                "type": "string"
                            },
                            "Protocol": {
                                "type": "string"
                            },
                            "SensorId": {
                                "type": "string"
                            },
                            "SourceDeviceAddress": {
                                "type": "string"
                            }
                        },
                        "type": "object"
                    }
                },
                "runAfter": {},
                "type": "ParseJson"
            },
            "Run_query_and_list_results": {
                "inputs": {
                    "body": "_GetWatchlist(\"@{variables('WatchlistName')}\") \n| where ip_address == \"@{body('Parse_JSON')?['SourceDeviceAddress']}\"",
